 root.className='prompt-palette';grid.className='prompt-palette-grid';actions.className='prompt-palette-actions';sfw.type='checkbox';sfwLabel.append(sfw,sfwText);preview.rows=3;preview.readOnly=true;previewLabel.append(previewTitle,preview);insert.type=reset.type='button';status.setAttribute('role','status');
